package cache

// EvictionPolicy описывает абстрактный, обобщенный (Generic) контракт для реализации стратегий
// вытеснения данных из оперативной памяти кэш-хранилища (LRU, LFU, FIFO, ARC).
//
// Выступает в роли изолированного контроллера памяти, который отслеживает статистику обращений
// к ключам и принимает математически обоснованное решение о том, какой элемент необходимо
// принудительно удалить (evict) при достижении лимита емкости хранилища (DataCapacity).
type EvictionPolicy[K comparable] interface {
	// OnGet регистрирует факт успешного чтения элемента по его ключу.
	// Критично для алгоритмов LRU (обновление времени доступа) и LFU (инкремент счетчика частоты).
	OnGet(key K)

	// OnSet фиксирует событие вставки нового или модификации существующего элемента кэша.
	OnSet(key K)

	// OnRemove оповещает стратегию о принудительном ручном удалении ключа из кэша.
	// Метод обязан мгновенно очистить внутренние индексы стратегии, предотвращая скрытые утечки памяти.
	OnRemove(key K)

	// Reset полностью сбрасывает внутреннее состояние, счетчики и очереди контроллера вытеснения.
	Reset()

	// Evict выполняет расчет и возвращает ключ «жертвы», подлежащий немедленному удалению из кэша.
	// Возвращает булев флаг false, если кэш пуст и вытеснять в данный момент нечего.
	Evict() (key K, ok bool)
}
